dashboard.definition:
{
  "title": "Training Lens",
  "description": "Recorded volume, consistency and activity history. Reported mode preserves source anomalies; Validated excludes affected distance/duration comparisons. Year grain uses snapshot history; Comparable YTD ends at the import calendar date. Empty charts mean no eligible data in the selection. Automatic selects the first available metric; invalid bookmarked IDs show an explicit unavailable state. Availability is snapshot-wide and refreshes every five minutes.",
  "visualizations": {
    "viz_0": {
      "type": "splunk.singlevalue",
      "title": "$volume_metadata:result.title$",
      "dataSources": {
        "primary": "volume_summary"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_1": {
      "type": "splunk.line",
      "title": "$volume_metadata:result.title$",
      "dataSources": {
        "primary": "volume_chart"
      },
      "options": {
        "nullValueDisplay": "gaps",
        "yAxisTitleText": "$volume_metadata:result.unit$",
        "xAxisTitleText": "Period"
      },
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_2": {
      "type": "splunk.table",
      "title": "Activities and coverage",
      "dataSources": {
        "primary": "table_2"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "training_lens",
            "dashboard": "activity_detail",
            "tokens": [
              {
                "token": "activity_id",
                "value": "row.activity_id.value"
              },
              {
                "token": "snapshot",
                "value": "row.snapshot_id.value"
              }
            ],
            "newTab": false
          }
        }
      ]
    }
  },
  "dataSources": {
    "dimensions": {
      "type": "ds.search",
      "name": "dimensions",
      "options": {
        "query": "| inputlookup training_lens_dimension_options | search [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ]",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "sport_options": {
      "type": "ds.chain",
      "name": "sport_options",
      "options": {
        "query": "| where dimension=\"sport\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All\" ] | dedup value | sort 0 label",
        "extend": "dimensions"
      }
    },
    "gear_options": {
      "type": "ds.chain",
      "name": "gear_options",
      "options": {
        "query": "| where dimension=\"gear\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All\" ] | dedup value | sort 0 label",
        "extend": "dimensions"
      }
    },
    "metric_options": {
      "type": "ds.search",
      "name": "metric_options",
      "options": {
        "query": "| inputlookup training_lens_metric_availability | search [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | where sport=$sport|s$ AND gear=$gear|s$ AND valid_count>0 AND metric_id IN (\"activities\",\"hours\",\"distance\",\"elevation\",\"active_days\",\"flagged\") | lookup training_lens_metric_catalog metric_id OUTPUT label sort_order prerequisite | stats first(label) AS label first(sort_order) AS sort_order max(refreshed_at) AS refreshed_at BY metric_id | eval label=if(now()-refreshed_at>900,label.\" \u00b7 cache stale\",label) | append [ | makeresults | eval metric_id=\"__auto__\",label=\"Automatic / first available\",sort_order=-1 ] | sort 0 sort_order metric_id",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "volume_options": {
      "type": "ds.chain",
      "name": "volume_options",
      "options": {
        "query": "| where metric_id=\"__auto__\" OR metric_id IN (\"activities\",\"hours\",\"distance\",\"elevation\",\"active_days\",\"flagged\")",
        "extend": "metric_options"
      }
    },
    "volume_metadata": {
      "type": "ds.chain",
      "name": "volume_metadata",
      "options": {
        "query": "| where metric_id!=\"__auto__\" AND ($volume|s$=\"__auto__\" OR metric_id=$volume|s$) | head 1 | lookup training_lens_metric_catalog metric_id OUTPUT label metric_unit imperial_unit | eval unit=if($units|s$=\"Imperial\",imperial_unit,metric_unit),title=label.\" (\".unit.\")\" | appendpipe [ stats count | where count=0 | eval metric_id=\"__none__\",unit=\"\",title=\"Choose an available metric \u00b7 cache pending or selection unavailable\" ] | fields metric_id title unit",
        "extend": "volume_options",
        "enableSmartSources": true
      }
    },
    "volume_aggregate": {
      "type": "ds.search",
      "name": "volume_aggregate",
      "options": {
        "query": "index=strava sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where ($grain|s$=\"Year\" OR (timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))))) | where $grain|s$!=\"Year\" OR $history_scope|s$!=\"Comparable YTD\" OR substr(local_date,6,5)<=comparison_month_day | eval metric_id=$volume_metadata:result.metric_id|s$ | eval eligible=case(metric_id=\"activities\",if(true(),1,0),metric_id=\"hours\",if(isnotnull(moving_time_s) AND ($quality_mode|s$!=\"Validated\" OR duration_valid=1),1,0),metric_id=\"distance\",if(isnotnull(distance_m) AND ($quality_mode|s$!=\"Validated\" OR distance_valid=1),1,0),metric_id=\"elevation\",if(isnotnull(elevation_gain_m),1,0),metric_id=\"active_days\",if(true(),1,0),metric_id=\"flagged\",if(true(),1,0)),numerator=case(metric_id=\"activities\",if(true(),1,null()),metric_id=\"hours\",if(isnotnull(moving_time_s) AND ($quality_mode|s$!=\"Validated\" OR duration_valid=1),moving_time_s,null()),metric_id=\"distance\",if(isnotnull(distance_m) AND ($quality_mode|s$!=\"Validated\" OR distance_valid=1),distance_m,null()),metric_id=\"elevation\",if(isnotnull(elevation_gain_m),elevation_gain_m,null()),metric_id=\"active_days\",if(true(),local_date,null()),metric_id=\"flagged\",if(true(),flagged,null())),denominator=case(metric_id=\"activities\",if(true(),1,null()),metric_id=\"hours\",if(isnotnull(moving_time_s) AND ($quality_mode|s$!=\"Validated\" OR duration_valid=1),1,null()),metric_id=\"distance\",if(isnotnull(distance_m) AND ($quality_mode|s$!=\"Validated\" OR distance_valid=1),1,null()),metric_id=\"elevation\",if(isnotnull(elevation_gain_m),1,null()),metric_id=\"active_days\",if(true(),1,null()),metric_id=\"flagged\",if(true(),1,null())) | eval bucket=case($grain|s$=\"Year\",coalesce(local_year,strftime(timestamp,\"%Y\")),$grain|s$=\"Month\",coalesce(local_month,strftime(timestamp,\"%Y-%m\")),true(),coalesce(local_week_start,strftime(relative_time(timestamp,\"@w1\"),\"%Y-%m-%d\"))),series=case(metric_id=\"zones\",\"Zone \".zone,metric_id IN (\"pace\",\"speed\") AND $sport|s$=\"All\",coalesce(sport,\"Unspecified\").if($split|s$=\"Gear\",\" \u00b7 \".coalesce(gear,\"Unspecified\"),\"\"),$split|s$=\"Sport\",coalesce(sport,\"Unspecified\"),$split|s$=\"Gear\",coalesce(gear,\"Unspecified\"),true(),\"Selected activities\") | stats sum(numerator) AS numerator sum(denominator) AS denominator max(numerator) AS peak median(numerator) AS midpoint avg(numerator) AS average dc(eval(if(eligible=1,local_date,null()))) AS days sum(eligible) AS valid_count count AS total_count BY bucket series metric_id | eval value=case(metric_id=\"activities\",if(valid_count>0,numerator,null()),metric_id=\"hours\",if(valid_count>0,numerator,null()),metric_id=\"distance\",if(valid_count>0,numerator,null()),metric_id=\"elevation\",if(valid_count>0,numerator,null()),metric_id=\"active_days\",days,metric_id=\"flagged\",if(valid_count>0,numerator,null())) | lookup training_lens_metric_catalog metric_id OUTPUT label metric_unit imperial_unit metric_factor imperial_factor precision | eval unit=if($units|s$=\"Imperial\",imperial_unit,metric_unit),value=round(value*if($units|s$=\"Imperial\",imperial_factor,metric_factor),precision),coverage=if(total_count>0,100*valid_count/total_count,null()),series_label=series.\" \u00b7 \".label.\" (\".unit.\")\" | fields bucket series_label value unit coverage | sort 0 bucket series_label",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "volume_chart": {
      "type": "ds.chain",
      "name": "volume_chart",
      "options": {
        "query": "| xyseries bucket series_label value | appendpipe [ where $grain|s$=\"Year\" | makecontinuous bucket span=1 | eval _expanded=1 ] | where $grain|s$!=\"Year\" OR _expanded=1 | fields - _expanded",
        "extend": "volume_aggregate"
      }
    },
    "volume_summary": {
      "type": "ds.search",
      "name": "volume_summary",
      "options": {
        "query": "index=strava sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where ($grain|s$=\"Year\" OR (timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))))) | where $grain|s$!=\"Year\" OR $history_scope|s$!=\"Comparable YTD\" OR substr(local_date,6,5)<=comparison_month_day | eval metric_id=$volume_metadata:result.metric_id|s$ | eval eligible=case(metric_id=\"activities\",if(true(),1,0),metric_id=\"hours\",if(isnotnull(moving_time_s) AND ($quality_mode|s$!=\"Validated\" OR duration_valid=1),1,0),metric_id=\"distance\",if(isnotnull(distance_m) AND ($quality_mode|s$!=\"Validated\" OR distance_valid=1),1,0),metric_id=\"elevation\",if(isnotnull(elevation_gain_m),1,0),metric_id=\"active_days\",if(true(),1,0),metric_id=\"flagged\",if(true(),1,0)),numerator=case(metric_id=\"activities\",if(true(),1,null()),metric_id=\"hours\",if(isnotnull(moving_time_s) AND ($quality_mode|s$!=\"Validated\" OR duration_valid=1),moving_time_s,null()),metric_id=\"distance\",if(isnotnull(distance_m) AND ($quality_mode|s$!=\"Validated\" OR distance_valid=1),distance_m,null()),metric_id=\"elevation\",if(isnotnull(elevation_gain_m),elevation_gain_m,null()),metric_id=\"active_days\",if(true(),local_date,null()),metric_id=\"flagged\",if(true(),flagged,null())),denominator=case(metric_id=\"activities\",if(true(),1,null()),metric_id=\"hours\",if(isnotnull(moving_time_s) AND ($quality_mode|s$!=\"Validated\" OR duration_valid=1),1,null()),metric_id=\"distance\",if(isnotnull(distance_m) AND ($quality_mode|s$!=\"Validated\" OR distance_valid=1),1,null()),metric_id=\"elevation\",if(isnotnull(elevation_gain_m),1,null()),metric_id=\"active_days\",if(true(),1,null()),metric_id=\"flagged\",if(true(),1,null())) | eval bucket=case($grain|s$=\"Year\",coalesce(local_year,strftime(timestamp,\"%Y\")),$grain|s$=\"Month\",coalesce(local_month,strftime(timestamp,\"%Y-%m\")),true(),coalesce(local_week_start,strftime(relative_time(timestamp,\"@w1\"),\"%Y-%m-%d\"))),series=case(metric_id=\"zones\",\"Zone \".zone,metric_id IN (\"pace\",\"speed\") AND $sport|s$=\"All\",coalesce(sport,\"Unspecified\").if($split|s$=\"Gear\",\" \u00b7 \".coalesce(gear,\"Unspecified\"),\"\"),$split|s$=\"Sport\",coalesce(sport,\"Unspecified\"),$split|s$=\"Gear\",coalesce(gear,\"Unspecified\"),true(),\"Selected activities\") | stats sum(numerator) AS numerator sum(denominator) AS denominator max(numerator) AS peak median(numerator) AS midpoint avg(numerator) AS average dc(eval(if(eligible=1,local_date,null()))) AS days sum(eligible) AS valid_count count AS total_count BY metric_id | eval value=case(metric_id=\"activities\",if(valid_count>0,numerator,null()),metric_id=\"hours\",if(valid_count>0,numerator,null()),metric_id=\"distance\",if(valid_count>0,numerator,null()),metric_id=\"elevation\",if(valid_count>0,numerator,null()),metric_id=\"active_days\",days,metric_id=\"flagged\",if(valid_count>0,numerator,null())) | lookup training_lens_metric_catalog metric_id OUTPUT label metric_unit imperial_unit metric_factor imperial_factor precision | eval unit=if($units|s$=\"Imperial\",imperial_unit,metric_unit),value=round(value*if($units|s$=\"Imperial\",imperial_factor,metric_factor),precision),coverage=if(total_count>0,100*valid_count/total_count,null()),series_label=label.\" (\".unit.\")\" | fields value",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "table_2": {
      "type": "ds.search",
      "name": "table_2",
      "options": {
        "query": "index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($activity_view|s$=\"Recent activities\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | eval display_distance=distance_m/if($units|s$=\"Imperial\",1609.344,1000) | sort 0 - timestamp | head 100 | table activity_id snapshot_id local_date activity_name sport display_distance moving_time_s average_hr relative_effort stream_status quality_flags | where $activity_view|s$=\"Recent activities\" | append [ search index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($activity_view|s$=\"Coverage\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | stats count AS activities count(average_hr) AS with_hr count(relative_effort) AS with_effort count(eval(stream_status=\"decoded\")) AS decoded_streams count(eval(stream_status=\"summary_only\")) AS summary_only | where $activity_view|s$=\"Coverage\" ] | append [ search index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($activity_view|s$=\"Annual changes\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where $history_scope|s$!=\"Comparable YTD\" OR substr(local_date,6,5)<=comparison_month_day | chart count OVER local_year BY sport limit=0 useother=f usenull=f | makecontinuous local_year span=1 | fillnull value=0 | untable local_year sport activities | sort 0 sport local_year | streamstats current=f window=1 last(activities) AS previous_year_activities BY sport | eval change_activities=activities-previous_year_activities, yoy_pct=if(previous_year_activities>0,round(100*change_activities/previous_year_activities,1),null()) | table local_year sport activities previous_year_activities change_activities yoy_pct | where $activity_view|s$=\"Annual changes\" ]",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    }
  },
  "inputs": {
    "time": {
      "type": "input.timerange",
      "title": "Period (Year grain uses history)",
      "options": {
        "token": "time",
        "defaultValue": "-1y,now"
      }
    },
    "snapshot": {
      "type": "input.text",
      "title": "Snapshot (latest or ID)",
      "options": {
        "token": "snapshot",
        "defaultValue": "latest"
      }
    },
    "sport": {
      "type": "input.dropdown",
      "title": "Sport",
      "dataSources": {
        "primary": "sport_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"value\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "sport",
        "defaultValue": "All",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "gear": {
      "type": "input.dropdown",
      "title": "Gear",
      "dataSources": {
        "primary": "gear_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"value\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "gear",
        "defaultValue": "All",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "quality_mode": {
      "type": "input.dropdown",
      "title": "Quality",
      "options": {
        "token": "quality_mode",
        "defaultValue": "Validated",
        "items": [
          {
            "label": "Validated",
            "value": "Validated"
          },
          {
            "label": "Reported",
            "value": "Reported"
          },
          {
            "label": "Flagged only",
            "value": "Flagged only"
          }
        ]
      }
    },
    "units": {
      "type": "input.dropdown",
      "title": "Units",
      "options": {
        "token": "units",
        "defaultValue": "Metric",
        "items": [
          {
            "label": "Metric",
            "value": "Metric"
          },
          {
            "label": "Imperial",
            "value": "Imperial"
          }
        ]
      }
    },
    "grain": {
      "type": "input.dropdown",
      "title": "Time grain",
      "options": {
        "token": "grain",
        "defaultValue": "Month",
        "items": [
          {
            "label": "Week",
            "value": "Week"
          },
          {
            "label": "Month",
            "value": "Month"
          },
          {
            "label": "Year",
            "value": "Year"
          }
        ]
      }
    },
    "history_scope": {
      "type": "input.dropdown",
      "title": "Annual scope",
      "options": {
        "token": "history_scope",
        "defaultValue": "Full years",
        "items": [
          {
            "label": "Full years",
            "value": "Full years"
          },
          {
            "label": "Comparable YTD",
            "value": "Comparable YTD"
          }
        ]
      }
    },
    "split": {
      "type": "input.dropdown",
      "title": "Group series",
      "options": {
        "token": "split",
        "defaultValue": "Sport",
        "items": [
          {
            "label": "Total",
            "value": "Total"
          },
          {
            "label": "Sport",
            "value": "Sport"
          },
          {
            "label": "Gear",
            "value": "Gear"
          }
        ]
      }
    },
    "volume": {
      "type": "input.dropdown",
      "title": "Metric \u00b7 volume",
      "dataSources": {
        "primary": "volume_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"metric_id\") | renameSeries(\"value\")"
      },
      "options": {
